'use strict';
const icons={bookmark:'<svg width="17" height="19" viewBox="0 0 20 22" fill="none" stroke="currentColor" stroke-width="1.5"><path d="M5 3h10v16l-5-3-5 3z"/></svg>',check:'<svg width="19" height="19" viewBox="0 0 22 22" fill="none" stroke="currentColor" stroke-width="1.5"><circle cx="11" cy="11" r="8"/><path d="m7 11 3 3 5-6"/></svg>'};
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const normalize=s=>s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,' ').trim();
let state={bookmarks:[],read:[]},storageAvailable=true,data,selectedPart='all',selectedTopic=null;
const params=new URLSearchParams(location.search);let bookmarksOnly=params.get('view')==='bookmarks';
try{const s=JSON.parse(localStorage.getItem('klh-study-v1')||'{}');for(const key of ['bookmarks','read'])state[key]=Array.isArray(s[key])?s[key].filter(x=>typeof x==='string'):[];}catch{storageAvailable=false;}
function save(){try{localStorage.setItem('klh-study-v1',JSON.stringify(state));}catch{storageAvailable=false;}if(!storageAvailable&&!document.querySelector('.storage-notice')){const n=document.createElement('div');n.className='storage-notice';n.setAttribute('role','status');n.textContent='Browser storage is unavailable. Your changes will last for this visit only.';document.body.append(n);}}
function toggle(key,id,value){if(!data.cases.some(c=>c.id===id))throw Error('Unknown case');const on=value??!state[key].includes(id);state[key]=state[key].filter(x=>x!==id);if(on)state[key].push(id);save();render();return{id,[key==='read'?'read':'bookmarked']:on};}
function button(key,c){const on=state[key].includes(c.id);return `<button class="icon-button ${on?'is-on':''}" data-action="${key}" data-id="${esc(c.id)}" aria-pressed="${on}" aria-label="${key==='read'?(on?'Mark unread: ':'Mark as read: '):(on?'Remove bookmark: ':'Bookmark: ')}${esc(c.title)}" title="${key==='read'?'Mark as read':'Bookmark'}">${icons[key==='read'?'check':'bookmark']}</button>`;}
function matching(){const q=normalize(document.getElementById('search')?.value||'');return data.cases.filter(c=>(!bookmarksOnly||state.bookmarks.includes(c.id))&&(!selectedTopic||c.topicIds.includes(selectedTopic))&&(selectedPart==='all'||c.topicIds.some(id=>data.topics.find(t=>t.id===id).partId===selectedPart))&&(!q||normalize([c.title,c.citation,...(c.alternateNames||[]),...c.syllabusCitations,c.citationNote||'',...c.topicIds.map(id=>data.topics.find(t=>t.id===id).title)].join(' ')).includes(q)));}
function render(){if(!data)return;const ids=new Set(data.cases.map(c=>c.id));const read=new Set(state.read.filter(id=>ids.has(id)));document.getElementById('overall-progress').textContent=`${read.size} of ${ids.size} cases read`;document.getElementById('progress-fill').style.width=`${100*read.size/ids.size}%`;document.querySelectorAll('[data-action]').forEach(b=>{const on=state[b.dataset.action].includes(b.dataset.id);b.classList.toggle('is-on',on);b.setAttribute('aria-pressed',String(on));});if(!document.getElementById('library'))return;const cases=matching(),matches=new Set(cases.map(c=>c.id));document.getElementById('result-count').textContent=`${cases.length} cases`;let html='';let seen=new Set();for(const t of data.topics){if(selectedTopic&&t.id!==selectedTopic||selectedPart!=='all'&&t.partId!==selectedPart)continue;const refs=data.references.filter(r=>r.topicId===t.id&&matches.has(r.caseId));if(!refs.length)continue;const unique=[...new Set(t.caseIds)];html+=`<section><div class="topic-heading"><span class="chapter">${data.topics.filter(x=>x.partId===t.partId).findIndex(x=>x.id===t.id)+1<10?'0':''}${data.topics.filter(x=>x.partId===t.partId).findIndex(x=>x.id===t.id)+1}</span><h2>${esc(t.title)}</h2><span class="topic-progress">${unique.filter(id=>read.has(id)).length} / ${unique.length} read</span></div><p class="topic-description">${esc(t.description.join(' · '))}</p>`;let section=null;for(const r of refs){const c=data.cases.find(c=>c.id===r.caseId);if(section!==r.section){section=r.section;if(section)html+=`<h3 class="section-label">${esc(section)}</h3>`;}const status=c.status==='secondary'?'<span class="status-note">Secondary full-text source</span>':c.status==='unresolved'?'<span class="status-note">Full text unavailable</span>':'';html+=`<article class="case-row"><span class="case-number">${String(r.number).padStart(2,'0')}</span><div><a class="case-name" href="/cases/${c.id}/">${esc(c.title)}</a><div class="case-citation">${esc(c.citation||r.citation.slice(c.title.length).replace(/^,\s*/,''))}${status}</div></div><div class="row-actions">${button('bookmarks',c)}${button('read',c)}<a class="read-link" href="/cases/${c.id}/">Read case <span aria-hidden="true">↗</span></a></div></article>`;seen.add(c.id);}html+='</section>';}document.getElementById('library').innerHTML=html||`<div class="empty"><h2>${bookmarksOnly?'No bookmarked cases yet':'No matching cases'}</h2><p>${bookmarksOnly?'Select the bookmark beside a case to save it here.':'Try a case name, docket number, or another topic.'}</p></div>`;}
document.addEventListener('click',e=>{const action=e.target.closest('[data-action]');if(action){const id=action.dataset.id,key=action.dataset.action;toggle(key,id);const replacement=document.querySelector(`[data-action="${key}"][data-id="${id}"]`);replacement?.focus();}const tab=e.target.closest('[data-part]');if(tab){selectedPart=tab.dataset.part;selectedTopic=null;document.querySelectorAll('[data-part]').forEach(x=>x.classList.toggle('selected',x===tab));render();}const topic=e.target.closest('[data-topic]');if(topic&&document.getElementById('library')){e.preventDefault();selectedTopic=topic.dataset.topic;selectedPart='all';bookmarksOnly=false;document.querySelectorAll('.topic-link').forEach(x=>x.classList.toggle('active',x===topic));document.querySelectorAll('[data-part]').forEach(x=>x.classList.toggle('selected',x.dataset.part==='all'));document.getElementById('sidebar').classList.remove('open');document.getElementById('menu').setAttribute('aria-expanded','false');render();document.getElementById('main').scrollIntoView({behavior:'smooth'});}});
document.getElementById('menu')?.addEventListener('click',()=>{const open=document.getElementById('sidebar').classList.toggle('open');document.getElementById('menu').setAttribute('aria-expanded',String(open));});
document.getElementById('search')?.addEventListener('input',render);
function registerWebMCP(){if(!document.modelContext?.registerTool)return;document.modelContext.registerTool({name:'search_cases',description:'Search the KLH case library by case title, alternate name, citation, or syllabus topic.',inputSchema:{type:'object',properties:{query:{type:'string'}},required:['query']},execute:({query})=>{const q=normalize(query),results=data.cases.filter(c=>normalize([c.title,c.citation,...(c.alternateNames||[]),...c.syllabusCitations,c.citationNote||'',...c.topicIds.map(id=>data.topics.find(t=>t.id===id).title)].join(' ')).includes(q)).slice(0,20).map(c=>({title:c.title,citation:c.citation,url:`${location.origin}/cases/${c.id}/`}));return{content:[{type:'text',text:JSON.stringify(results)}]};}});for(const [name,description,field] of [['set_case_bookmark','Bookmark or unbookmark a case in this browser.','bookmarks'],['set_case_read','Mark a case as read or unread in this browser.','read']])document.modelContext.registerTool({name,description,inputSchema:{type:'object',properties:{case_id:{type:'string'},value:{type:'boolean'}},required:['case_id','value']},execute:({case_id,value})=>({content:[{type:'text',text:JSON.stringify(toggle(field,case_id,value))}]})});}
fetch('/data/index.json').then(r=>{if(!r.ok)throw Error('Could not load case library');return r.json();}).then(d=>{data=d;selectedTopic=params.get('topic');document.getElementById('topics').innerHTML=data.parts.map(p=>`<div class="topic-part">${p.id==='part-1'?'I.':'II.'} ${esc(p.title)}</div>${data.topics.filter(t=>t.partId===p.id).map((t,i)=>`<a class="topic-link" data-topic="${t.id}" href="/?topic=${t.id}"><span class="topic-num">${String(i+1).padStart(2,'0')}</span><span>${esc(t.title)}</span></a>`).join('')}`).join('');if(bookmarksOnly){document.querySelector('.eyebrow').textContent='YOUR BOOKMARKS';document.querySelector('h1').textContent='Your saved reading.';document.querySelectorAll('.primary-nav a').forEach(a=>a.classList.toggle('active',a.href.includes('bookmarks')));}registerWebMCP();render();}).catch(e=>{const target=document.getElementById('library');if(target)target.innerHTML='<p class="notice">The case index could not be loaded. Please refresh to try again.</p>';});
